use mdd_input::snapshot::{CaptureLimits,InputKind,InputSpec,Snapshot};
use mdd_query::{budget::{bounded_channel,BoundedReceiver,BoundedSender,BudgetLimits,BudgetPool,BudgetScope,Resource,RuntimeBudget,QueueEvent},executor::{prepare,execute_into,Control,ExecutionLimits,ExecutionMode,FactSource,RelationSchema,PendingDelivery,PreparedQuery,facts::{MemoryCatalog,Table}},ir::{Column,DataType,FactLayer,Node,QueryIr,Row,Value,IR_VERSION,TEXT_VERSION}};
use mdd_session::{Lifecycle,ResourceLimits,SessionHandle,QueryHandle,cancellation::QueryCancellation};
use mdd_types::{Completeness,Coverage,DecimalU64,ErrorCode,MddError,MddResult,result::{ResultIdentity,TerminalBuilder}};
use serde_json::{json,Value as Json};
use std::{collections::{BTreeMap,BTreeSet},path::PathBuf,sync::{Arc,Barrier,atomic::{AtomicUsize,Ordering}},time::Duration};

struct Source{inner:MemoryCatalog,fail_after_prepare:bool,calls:AtomicUsize}
impl FactSource for Source{
 fn identity(&self)->&str{self.inner.identity()}
 fn snapshot_id(&self)->&str{self.inner.snapshot_id()}
 fn catalog_epoch(&self)->DecimalU64{self.inner.catalog_epoch()}
 fn relation_schema(&self,name:&str)->MddResult<RelationSchema>{self.inner.relation_schema(name)}
 fn require_layers(&self,layers:&BTreeSet<FactLayer>)->MddResult<()>{let call=self.calls.fetch_add(1,Ordering::SeqCst);if self.fail_after_prepare&&call>0{Err(MddError::new(ErrorCode::IncompleteFacts,"injected.layer","required facts became unavailable after prepare"))}else{self.inner.require_layers(layers)}}
 fn validate_entity(&self,e:&mdd_facts::EntityRef)->MddResult<()>{self.inner.validate_entity(e)}
 fn scan<'a>(&'a self,name:&str)->MddResult<Box<dyn Iterator<Item=MddResult<Row>>+'a>>{self.inner.scan(name)}
 fn read_code_bytes(&self,e:&mdd_facts::EntityRef)->MddResult<Option<&[u8]>>{self.inner.read_code_bytes(e)}
}
struct Fixture{life:Lifecycle,session:SessionHandle,query:QueryHandle,cancel:QueryCancellation,source:Source,prepared:PreparedQuery,runtime:RuntimeBudget,pool:BudgetPool,missing:bool}
fn setup(count:u64,deadline_ms:u64,missing:bool)->Fixture{
 let snapshot=Arc::new(Snapshot::capture(&[InputSpec{path:PathBuf::from("tests/fixtures/generated/minimal-035.dex"),kind:InputKind::RawDex,expected_sha256:None}],CaptureLimits::default()).unwrap());
 let snapshot_id=snapshot.manifest().snapshot_id.clone();let life=Lifecycle::new(ResourceLimits::default()).unwrap();
 let h=life.register_snapshot(snapshot).unwrap();let session=life.open_session(&h,ResourceLimits::default()).unwrap();
 let inner=MemoryCatalog::new(snapshot_id.clone(),DecimalU64(0),BTreeMap::from([("rows".into(),Table{columns:vec![Column{id:"n".into(),display_name:"n".into(),data_type:DataType::U64,nullable:false}],required_layers:vec![FactLayer::Structure],rows:(0..count).map(|n|vec![Value::U64(DecimalU64(n))]).collect()})]),BTreeSet::from([FactLayer::Structure])).unwrap();
 let source=Source{inner,fail_after_prepare:missing,calls:AtomicUsize::new(0)};
 let prepared=prepare(QueryIr{schema_version:IR_VERSION.into(),text_semantics:TEXT_VERSION.into(),snapshot_id,catalog_epoch:DecimalU64(0),require_stable_order:false,root:Node::Scan{relation:"rows".into()}},&source).unwrap();
 let query=life.prepare_query(&session,prepared.runtime_binding().unwrap(),ResourceLimits{deadline_ms,..ResourceLimits::default()}).unwrap();
 life.start_query(&session,&query,1).unwrap();let cancel=life.cancellation_token(&query).unwrap();
 let limits=BudgetLimits::default();let global=BudgetPool::global("independent-delivery".into(),limits.clone()).unwrap();
 let worker=global.child(cancel.worker_owner_id().unwrap(),BudgetScope::Worker,limits.clone()).unwrap();let sess=worker.child(session.id().into(),BudgetScope::Session,limits.clone()).unwrap();let pool=sess.child(query.id().into(),BudgetScope::Query,limits).unwrap();
 let runtime=RuntimeBudget::new(pool.clone(),cancel.clone()).unwrap();Fixture{life,session,query,cancel,source,prepared,runtime,pool,missing}
}
fn terminal(f:&Fixture)->TerminalBuilder{TerminalBuilder::new(ResultIdentity{request_id:"test".into(),operation:"query".into(),profile:"native-unqualified".into(),sql_dialect:None,session_id:Some(f.session.id().into()),snapshot_id:Some(f.source.snapshot_id().into()),catalog_epoch:Some(DecimalU64(0)),query_id:Some(f.query.id().into()),schema_id:Some(f.prepared.runtime_binding().unwrap().schema_id)},Coverage{scope_id:"synthetic".into(),input:Completeness::Complete,facts:if f.missing{Completeness::Unknown}else{Completeness::Complete},required_layers:vec!["structure".into()],issues:vec![]}).unwrap()}
fn queue(f:&Fixture)->(BoundedSender<Row>,BoundedReceiver<Row>){bounded_channel(f.pool.clone(),Some(f.cancel.clone()),8).unwrap()}
fn produce(f:&Fixture,s:&BoundedSender<Row>,max:u64)->MddResult<PendingDelivery>{let mut control=Control::new(ExecutionLimits{max_output_rows:max,..ExecutionLimits::default()}).with_runtime(f.runtime.clone());execute_into(&f.prepared,&f.source,ExecutionMode::Streaming,&mut control,terminal(f),s)}
fn queued(f:&Fixture)->u64{f.pool.usage().unwrap().used.get(&Resource::QueueItems).map_or(0,|x|x.0)}
fn drain(r:&mut BoundedReceiver<Row>)->Json{let mut items=Vec::new();let mut terminal=json!({"status":"missing"});for _ in 0..16{match r.receive(){Ok(QueueEvent::Data(v))=>{let row=serde_json::to_value(v.payload()).unwrap();let ack=v.acknowledge();items.push(json!({"row":row,"ack":match ack{Ok(())=>json!({"status":"ok"}),Err(e)=>json!({"status":"error","error":e})}}));},Ok(QueueEvent::End(v))=>{terminal=match v{Ok(())=>json!({"status":"ok"}),Err(e)=>json!({"status":"error","error":e})};break},Err(e)=>{terminal=json!({"status":"receive_error","error":e});break}}}json!({"items":items,"end":terminal})}
fn result<T:serde::Serialize>(x:MddResult<T>)->Json{match x{Ok(v)=>json!({"status":"ok","value":v}),Err(e)=>json!({"status":"error","error":e})}}
fn success(count:u64)->Json{let f=setup(count,30_000,false);let(s,mut r)=queue(&f);let mut pending=produce(&f,&s,100).unwrap();let before=f.cancel.status().unwrap();let n=queued(&f);let observed=drain(&mut r);let receipt=r.into_delivery_receipt();let final_out=match receipt{Ok(mut receipt)=>result(receipt.finish(&mut pending)),Err(e)=>json!({"status":"error","error":e})};json!({"case":if count==0{"zero"}else{"success"},"status_before":before,"queued_before":n,"drain":observed,"final":final_out,"status_after":f.cancel.status().unwrap()})}
fn unread()->Json{let f=setup(4,30_000,false);let(s,r)=queue(&f);let pending=produce(&f,&s,100).unwrap();let before=f.cancel.status().unwrap();let n=queued(&f);let receipt=match r.into_delivery_receipt(){Ok(_)=>json!({"status":"unexpected_ok"}),Err(e)=>json!({"status":"error","error":e})};let after=f.cancel.status().unwrap();drop(pending);json!({"case":"unread","status_before":before,"queued_before":n,"receipt":receipt,"status_after":after})}
fn abandoned()->Json{let f=setup(4,30_000,false);let(s,mut r)=queue(&f);let pending=produce(&f,&s,100).unwrap();let packet=match r.receive(){Ok(QueueEvent::Data(v))=>v,_=>panic!("expected data")};drop(packet);let status=f.cancel.status().unwrap();drop(r);drop(pending);json!({"case":"unacked_drop","status":status})}
fn consumer_drop()->Json{let f=setup(4,30_000,false);let(s,r)=queue(&f);let pending=produce(&f,&s,100).unwrap();drop(r);let status=f.cancel.status().unwrap();drop(pending);json!({"case":"consumer_drop","status":status})}
fn partial()->Json{let f=setup(4,30_000,false);let(s,mut r)=queue(&f);let mut pending=produce(&f,&s,2).unwrap();let observed=drain(&mut r);let out=match r.into_delivery_receipt(){Ok(mut receipt)=>result(receipt.finish(&mut pending)),Err(e)=>json!({"status":"error","error":e})};json!({"case":"partial_error","drain":observed,"final":out,"status":f.cancel.status().unwrap()})}
fn interruption(mode:&str)->Json{let f=setup(4,if mode=="deadline"{500}else{30_000},false);let(s,mut r)=queue(&f);let mut pending=produce(&f,&s,100).unwrap();match mode{"cancel"=>{f.cancel.cancel().unwrap();},"worker_lost"=>{f.life.worker_lost("independent worker loss").unwrap();},"deadline"=>std::thread::sleep(Duration::from_millis(600)),_=>unreachable!()};let observed=drain(&mut r);let out=match r.into_delivery_receipt(){Ok(mut receipt)=>result(receipt.finish(&mut pending)),Err(e)=>json!({"status":"error","error":e})};json!({"case":mode,"drain":observed,"final":out,"status":f.cancel.status().unwrap()})}
fn wrong_query()->Json{let a=setup(4,30_000,false);let b=setup(4,30_000,false);let(sa,mut ra)=queue(&a);let(sb,mut rb)=queue(&b);let mut pa=produce(&a,&sa,100).unwrap();let mut pb=produce(&b,&sb,100).unwrap();let da=drain(&mut ra);let db=drain(&mut rb);let mut xa=ra.into_delivery_receipt().unwrap();let mut xb=rb.into_delivery_receipt().unwrap();let wrong=result(xa.finish(&mut pb));let before_a=a.cancel.status().unwrap();let before_b=b.cancel.status().unwrap();let right_a=result(xa.finish(&mut pa));let right_b=result(xb.finish(&mut pb));json!({"case":"wrong_query","a_drain":da,"b_drain":db,"wrong":wrong,"a_before":before_a,"b_before":before_b,"a_final":right_a,"b_final":right_b,"a_after":a.cancel.status().unwrap(),"b_after":b.cancel.status().unwrap()})}
fn wrong_queue_same_query()->Json{let f=setup(4,30_000,false);let(s1,_r1)=queue(&f);let(s2,mut r2)=queue(&f);let mut pending=produce(&f,&s1,100).unwrap();s2.send(vec![Value::U64(DecimalU64(99))],16).unwrap();s2.finish(Ok(())).unwrap();let observed=drain(&mut r2);let mut receipt=r2.into_delivery_receipt().unwrap();let wrong=result(receipt.finish(&mut pending));let status=f.cancel.status().unwrap();drop(receipt);let after=f.cancel.status().unwrap();drop(pending);json!({"case":"wrong_queue_same_query","drain":observed,"wrong":wrong,"status_before_receipt_drop":status,"status_after_receipt_drop":after})}
fn out_of_order_ack()->Json{let f=setup(4,30_000,false);let(s,mut r)=queue(&f);let pending=produce(&f,&s,100).unwrap();let first=match r.receive(){Ok(QueueEvent::Data(x))=>x,_=>panic!("first packet missing")};let second=match r.receive(){Ok(QueueEvent::Data(x))=>x,_=>panic!("second packet missing")};let ack=result(second.acknowledge());let status=f.cancel.status().unwrap();drop(first);drop(r);drop(pending);json!({"case":"out_of_order_ack","ack":ack,"status":status})}
fn missing()->Json{let f=setup(1,30_000,true);let(s,mut r)=queue(&f);let out=produce(&f,&s,100);let observed=match out{Ok(mut p)=>{let d=drain(&mut r);let end=match r.into_delivery_receipt(){Ok(mut q)=>result(q.finish(&mut p)),Err(e)=>json!({"status":"error","error":e})};json!({"producer":"pending","drain":d,"final":end})},Err(e)=>json!({"producer":"error","error":e})};json!({"case":"missing_layer","observation":observed,"status":f.cancel.status().unwrap()})}
fn cancel_before_claim()->Json{let f=setup(1,30_000,false);let(s,mut r)=queue(&f);f.cancel.cancel().unwrap();let producer=match produce(&f,&s,100){Ok(_)=>json!({"status":"unexpected_pending"}),Err(e)=>json!({"status":"error","error":e})};let end=drain(&mut r);json!({"case":"cancel_before_claim","producer":producer,"drain":end,"status":f.cancel.status().unwrap()})}
fn race()->Json{let mut cases=Vec::new();for _ in 0..20{let f=setup(1,30_000,false);let(s,mut r)=queue(&f);let mut pending=produce(&f,&s,100).unwrap();let _=drain(&mut r);let mut receipt=r.into_delivery_receipt().unwrap();let gate=Arc::new(Barrier::new(2));let g=gate.clone();let handle=std::thread::spawn(move||{g.wait();result(receipt.finish(&mut pending))});gate.wait();let cancel=result(f.cancel.cancel());let finish=handle.join().unwrap();cases.push(json!({"finish":finish,"cancel":cancel,"final_status":f.cancel.status().unwrap()}));}json!({"case":"finish_cancel_race","iterations":cases})}
fn main(){let records=vec![success(4),success(0),unread(),abandoned(),consumer_drop(),partial(),interruption("cancel"),interruption("deadline"),interruption("worker_lost"),wrong_query(),wrong_queue_same_query(),out_of_order_ack(),missing(),cancel_before_claim(),race()];println!("{}",json!({"records":records,"profiles_admitted":false,"scope":"synthetic public executor/queue/lifecycle; no worker or production transport"}));}
